  1	class BinarySearch {
  2	    private static final int NOT_FOUND = -1;
  3	    private static final int[] SAMPLE_NUMBERS = { 2, 3, 4, 10, 40 };
  4	    private static final int SAMPLE_TARGET = 10;
  5	
  6	    static int binarySearch(int[] sortedNumbers, int target) {
  7	        if (sortedNumbers == null) {
  8	            throw new IllegalArgumentException("Array must not be null");
  9	        }
 10	
 11	        SearchInput input = new SearchInput(sortedNumbers, target);
 12	        SearchBounds bounds = input.bounds();
 13	
 14	        while (bounds.hasRemainingValues()) {
 15	            int middle = bounds.midpoint();
 16	
 17	            if (input.matches(middle)) {
 18	                return middle;
 19	            }
 20	
 21	            bounds = input.nextBounds(bounds, middle);
 22	        }
 23	
 24	        return NOT_FOUND;
 25	    }
 26	
 27	    private static String formatSearchResult(int index) {
 28	        return SearchResult.fromIndex(index).message();
 29	    }
 30	
 31	    public static void main(String[] args) {
 32	        runDemo();
 33	    }
 34	
 35	    private static void runDemo() {
 36	        int result = binarySearch(SAMPLE_NUMBERS, SAMPLE_TARGET);
 37	        System.out.println(formatSearchResult(result));
 38	    }
 39	
 40	    private static final class SearchResult {
 41	        private final int index;
 42	
 43	        private SearchResult(int index) {
 44	            this.index = index;
 45	        }
 46	
 47	        private static SearchResult fromIndex(int index) {
 48	            return new SearchResult(index);
 49	        }
 50	
 51	        private String message() {
 52	            if (index == NOT_FOUND) {
 53	                return "Element is not present in array";
 54	            }
 55	
 56	            return "Element is present at index " + index;
 57	        }
 58	    }
 59	
 60	    private static final class SearchInput {
 61	        private final int[] sortedNumbers;
 62	        private final int target;
 63	
 64	        private SearchInput(int[] sortedNumbers, int target) {
 65	            this.sortedNumbers = sortedNumbers;
 66	            this.target = target;
 67	        }
 68	
 69	        private boolean matches(int index) {
 70	            return sortedNumbers[index] == target;
 71	        }
 72	
 73	        private SearchBounds nextBounds(SearchBounds currentBounds, int middle) {
 74	            if (targetIsAfter(middle)) {
 75	                return currentBounds.after(middle);
 76	            }
 77	
 78	            return currentBounds.before(middle);
 79	        }
 80	
 81	        private SearchBounds bounds() {
 82	            return new SearchBounds(0, sortedNumbers.length - 1);
 83	        }
 84	
 85	        private boolean targetIsAfter(int index) {
 86	            return sortedNumbers[index] < target;
 87	        }
 88	    }
 89	
 90	    private static final class SearchBounds {
 91	        private final int left;
 92	        private final int right;
 93	
 94	        private SearchBounds(int left, int right) {
 95	            this.left = left;
 96	            this.right = right;
 97	        }
 98	
 99	        private boolean hasRemainingValues() {
100	            return left <= right;
101	        }
102	
103	        private int midpoint() {
104	            return left + (right - left) / 2;
105	        }
106	
107	        private SearchBounds after(int middle) {
108	            return new SearchBounds(middle + 1, right);
109	        }
110	
111	        private SearchBounds before(int middle) {
112	            return new SearchBounds(left, middle - 1);
113	        }
114	    }
115	}

